static inline const YieldTableEntry* get_agb_yield_table(double Z, int* n) {
    if (Z < 0.010) { *n = N_AGB_MASS_BINS_Z0007; return g_agb_yields_z0007; }
    else if (Z < 0.022) { *n = N_AGB_MASS_BINS_Z0014; return g_agb_yields_z0014; }
    else { *n = N_AGB_MASS_BINS_Z003; return g_agb_yields_z003; }
}

static inline double interp_agb_yield(const YieldTableEntry* t, int n, double m, ElementIndex e) {
    int i; for (i = 0; i < n - 1; i++) if (m <= t[i + 1].mass) break;
    if (m <= t[0].mass) return t[0].yields[e];
    if (m >= t[n - 1].mass) return t[n - 1].yields[e];
    double f = (m - t[i].mass) / (t[i + 1].mass - t[i].mass);
    return t[i].yields[e] + f * (t[i + 1].yields[e] - t[i].yields[e]);
}

